CREATE TABLE "model_runs" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "model_runs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer DEFAULT current_setting('sift.user')::integer NOT NULL,
	"account_id" text NOT NULL,
	"message_id" text NOT NULL,
	"model" text NOT NULL,
	"started_at" bigint NOT NULL,
	"finished_at" bigint,
	"outcome" text,
	"error" text,
	"input_tokens" integer DEFAULT 0 NOT NULL,
	"output_tokens" integer DEFAULT 0 NOT NULL,
	"cost_usd" double precision DEFAULT 0 NOT NULL,
	"retried_at" bigint,
	CONSTRAINT "model_runs_own" UNIQUE("user_id","id"),
	CONSTRAINT "model_runs_outcome" CHECK ("model_runs"."outcome" IN ('judged', 'failed'))
);
